-- OUMMAH Boycott — correction priorité marque scannée + extension catalogue.
-- Périmètre strict : module Boycott uniquement.
-- Une marque exacte doit gagner sur un lien de groupe indirect (ex. Pepsi > SodaStream/PepsiCo).

update public.boycott_entities
set aliases = ARRAY['Pepsi-Cola','Pepsi Cola','Pepsi Max','Pepsi Zero Sugar']::text[],
    updated_at = now()
where slug = 'pepsi';

on conflict (slug) do update set
  name = excluded.name,
  aliases = excluded.aliases,
  category = excluded.category,
  parent_group = excluded.parent_group,
  summary = excluded.summary,
  evidence_kind = excluded.evidence_kind,
  sources = excluded.sources,
  last_verified_at = excluded.last_verified_at,
  is_active = excluded.is_active,
  updated_at = now();
